sql_query:
SELECT "Originial publication or Follow-up"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Originial publication or Follow-up", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Head and Neck' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Originial publication or Follow-up" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Originial publication or Follow-up", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Head and Neck' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_is_follow_up(source_value) AS "is_follow_up"
FROM base;
